/* ECHO / Local-first audience and creator journeys. All dialogue remains authored. */
let journeyData={interests:[],progress:{},completed:[],audition:[],notes:[],spotlight:0};try{journeyData={...journeyData,...JSON.parse(localStorage.getItem('echo-original-journey')||'{}')}}catch{}
const beforeWorldRender=render,beforeWorldWatch=watch,beforeWorldStudio=studio,beforeWorldResults=results,beforeWorldNext=next;
function saveJourney(){try{localStorage.setItem('echo-original-journey',JSON.stringify(journeyData))}catch{}}
function checkpoint(){if(state.view!=='watch')return;journeyData.progress[state.topic]={turn:state.turn,elapsed:state.elapsed,date:Date.now()};saveJourney()}
function go(view){checkpoint();close();state.view=view;state.branch=[];state.branchActive=null;state.customLine='';render();window.scrollTo({top:0,behavior:'smooth'})}
function openEpisode(i,resume=false){checkpoint();close();state.view='watch';state.topic=i;const p=resume?journeyData.progress[i]:null;state.turn=p?.turn||0;state.elapsed=p?.elapsed||0;state.branch=[];state.branchActive=null;state.customLine='';state.playing=true;state.question='';state.vote=null;render();window.scrollTo({top:0,behavior:'smooth'})}
function latestProgress(){return Object.entries(journeyData.progress).filter(([i,p])=>p.turn>0&&!journeyData.completed.includes(+i)).sort((a,b)=>b[1].date-a[1].date)[0]}
const worlds=[{title:'The future needs a human.',desc:'Trust, work, and the choices we hand over.',cat:'TECHNOLOGY',accent:0},{title:'Who gets to be creative?',desc:'Originality, ownership, and the story behind the work.',cat:'CULTURE',accent:1},{title:'A friend who disagrees.',desc:'Companionship, honesty, and digital relationships.',cat:'HUMAN BEHAVIOR',accent:2}];
function orderedTopics(){let order=[0,1,2];if(journeyData.interests.length){order.sort((a,b)=>Number(journeyData.interests.includes(b))-Number(journeyData.interests.includes(a)))}return order}
function home(){const spotlight=journeyData.spotlight||0,p=people[spotlight],latest=latestProgress();const prefs=journeyData.interests.length>0;$('#main').innerHTML=`<div class="world-top"><span class="eyebrow">${prefs?'YOUR CORNER OF THE CONVERSATION':'A WORLD OF ORIGINAL MINDS'}</span><button id="tune-feed">${prefs?'Tune your interests':'Make it yours'} ↗</button></div><a class="lab-entry" href="lab/"><span>NEW / CHARACTER LAB</span><strong>Meet Nova in 3D.</strong><span>Speech, expression & holographic entrances ↗</span></a><section class="world-hero"><div class="hero-story"><div class="issue"><i></i> SEASON 01 / HUMAN, AFTER ALL</div><h1>Find a mind.<br>Change <em>yours.</em></h1><p>Meet characters worth listening to. Ask the question that changes the room. Give your own imagination a voice.</p><div class="hero-ctas"><button class="primary" id="enter-world">Enter the conversation <span>↗</span></button><button class="secondary" id="hero-create">Create a mind</button></div><div class="hero-note">3 SHORT EPISODES · YOUR CHOICES SHAPE THE EXCHANGE</div></div><div class="hero-art"><div class="hero-orbit"><i></i></div><div class="hero-portrait" id="hero-portrait">${face(spotlight)}</div><div class="portrait-id"><div><span id="spotlight-role">${p.role}</span><strong id="spotlight-name">${p.name}</strong></div><button class="mind-index" id="spotlight-profile" aria-label="Meet featured character">↗</button></div><div class="hero-cast">${people.map((p,i)=>`<button class="${i===spotlight?'selected':''}" data-spotlight="${i}">${p.name} / 0${i+1}</button>`).join('')}</div></div></section><div class="editorial-line"><span id="spotlight-quote"><strong>${p.name}’s point of view:</strong> “${p.stance}”</span><button id="hero-follow">${state.following.includes(p.name)?'Following ✓':'Follow this mind +'}</button></div>
<section class="world-section"><div class="world-section-head"><div><h2>${latest?'Pick up the thread.':'Your first move.'}</h2><p>${latest?'Your place in the conversation is saved.':'One good question is enough to start.'}</p></div><span class="soft-pill">Saved on this device</span></div><div class="return-row"><button class="resume-card" id="resume-card"><span class="round-play">▶</span><div style="flex:1"><span class="eyebrow">${latest?'CONTINUE WATCHING':'START HERE / EPISODE 01'}</span><h3>${topics[latest?+latest[0]:0].title}</h3>${latest?`<div class="track"><div style="width:${Math.round(latest[1].turn/(scripts[+latest[0]].length-1)*100)}%"></div></div>`:''}<p>${latest?'Resume at exchange '+(latest[1].turn+1):'Nova sees possibility. Atlas wants proof. Where do you stand?'}</p></div><span>↗</span></button><div class="next-seat"><span class="seat-symbol">✳</span><div><span class="eyebrow" style="font-size:8px">${state.avatar?'YOUR CHARACTER’S NEXT CHAPTER':'THE CREATOR PATH'}</span><h3>${state.avatar?esc(state.avatar.name)+' is ready for more.':'There’s a seat with your name on it.'}</h3><p>${state.avatar?'Try an audition, then direct their next line.':'A name. A worldview. A first appearance.'}</p><button id="next-seat">${state.avatar?'Go backstage':'Create my first mind'} ↗</button></div></div></div></section>
<section class="world-section"><div class="world-section-head"><div><h2>${prefs?'Picked around your curiosity.':'Three questions. Many sides.'}</h2><p>A complete first season. Watch at your own pace.</p></div><div class="season-row" aria-label="${journeyData.completed.length} of 3 episodes finished">${[0,1,2].map(i=>`<i class="${journeyData.completed.includes(i)?'done':''}"></i>`).join('')}<span style="font-size:9px;color:#91a8a4;margin-left:6px">${journeyData.completed.length}/3</span></div></div><div class="world-episodes">${orderedTopics().map(i=>`<button class="story-card" data-story="${i}"><div class="story-visual"><span class="story-number">0${i+1}</span>${face(i)}<span class="story-label">${worlds[i].cat} / ${journeyData.completed.includes(i)?'WATCHED':'CHAPTER 0'+(i+1)}</span><span class="story-play">▶</span></div><div class="story-copy"><span class="eyebrow">HUMAN, AFTER ALL</span><h3>${worlds[i].title}</h3><p>${worlds[i].desc}</p><div class="story-foot"><span>${scripts[i].length} exchanges · Interactive</span><span>${journeyData.progress[i]?.turn&&!journeyData.completed.includes(i)?'Resume ↗':'Watch ↗'}</span></div></div></button>`).join('')}</div></section>
<section class="world-section"><div class="world-section-head"><div><h2>${state.following.length?'The minds in your orbit.':'People make characters. You make connections.'}</h2><p>Follow a perspective you want to hear again.</p></div><button id="browse-minds">Explore ↗</button></div><div class="world-minds">${[0,1,2].sort((a,b)=>Number(state.following.includes(people[b].name))-Number(state.following.includes(people[a].name))).map(i=>`<article class="mind-tile">${face(i)}<span class="eyebrow" style="color:${people[i].color}">${people[i].role}</span><h3>${people[i].name}</h3><p>“${people[i].stance}”</p><div class="mind-actions"><button class="follow-pill" data-follow-home="${i}">${state.following.includes(people[i].name)?'Following ✓':'Follow +'}</button><button data-meet="${i}">Meet ${people[i].name} ↗</button></div></article>`).join('')}</div></section>
<div class="world-studio-banner"><div><span class="eyebrow">FROM AUDIENCE TO AUTHOR</span><h2>Someone only you<br>could imagine.</h2><p>Give them a belief. Give them a doubt. Watch what happens when your character meets a different mind.</p></div><button class="primary" id="banner-create">${state.avatar?'Open my studio':'Build my first mind'} ↗</button></div><p class="introduction-note">Prototype world · Authored dialogue · Local progress · No real broadcast or earnings</p>`;
$('#tune-feed').onclick=interests;$('#enter-world').onclick=()=>openEpisode(orderedTopics()[0]);$('#hero-create').onclick=create;$('#resume-card').onclick=()=>openEpisode(latest?+latest[0]:0,!!latest);$('#next-seat').onclick=()=>state.avatar?audition():create();$('#browse-minds').onclick=()=>go('discover');$('#banner-create').onclick=()=>state.avatar?go('studio'):create();$('#spotlight-profile').onclick=()=>profile(journeyData.spotlight);$('#hero-follow').onclick=()=>{toggleFollow(journeyData.spotlight);$('#hero-follow').textContent=state.following.includes(people[journeyData.spotlight].name)?'Following ✓':'Follow this mind +'};
$$('[data-spotlight]').forEach(b=>b.onclick=()=>{journeyData.spotlight=+b.dataset.spotlight;saveJourney();const p=people[journeyData.spotlight];$('#hero-portrait').innerHTML=face(journeyData.spotlight);$('#spotlight-name').textContent=p.name;$('#spotlight-role').textContent=p.role;$('#spotlight-quote').innerHTML=`<strong>${p.name}’s point of view:</strong> “${p.stance}”`;$('#hero-follow').textContent=state.following.includes(p.name)?'Following ✓':'Follow this mind +';$$('[data-spotlight]').forEach(x=>x.classList.toggle('selected',x===b));initFaces()});$$('[data-story]').forEach(b=>b.onclick=()=>openEpisode(+b.dataset.story,true));$$('[data-follow-home]').forEach(b=>b.onclick=()=>{toggleFollow(+b.dataset.followHome);b.textContent=state.following.includes(people[+b.dataset.followHome].name)?'Following ✓':'Follow +'});$$('[data-meet]').forEach(b=>b.onclick=()=>profile(+b.dataset.meet));}
function toggleFollow(i){const p=getPerson(i);if(state.following.includes(p.name))state.following=state.following.filter(n=>n!==p.name);else state.following.push(p.name);persist();toast(state.following.includes(p.name)?`${p.name} is now in your orbit`:`Unfollowed ${p.name}`)}
function interests(){let picked=[...journeyData.interests];modal(`<span class="eyebrow">MAKE A LITTLE SPACE FOR CURIOSITY</span><h2 id="modal-title">What draws you in?</h2><p>Choose the conversations you want to see first. You can change this whenever you like.</p><div class="choice-grid">${worlds.map((w,i)=>`<button class="interest-choice ${picked.includes(i)?'selected':''}" data-interest="${i}"><strong>${w.cat.toLowerCase().replace(/^./,c=>c.toUpperCase())}</strong><span>${w.desc}</span></button>`).join('')}</div><div class="modal-actions"><button class="secondary" id="all-interests">Keep it open</button><button class="primary" id="save-interests">Make it mine ↗</button></div>`);$$('[data-interest]').forEach(b=>b.onclick=()=>{const i=+b.dataset.interest;picked=picked.includes(i)?picked.filter(n=>n!==i):[...picked,i];b.classList.toggle('selected',picked.includes(i))});$('#save-interests').onclick=()=>{journeyData.interests=picked;saveJourney();go('home');toast('Your home now puts these conversations first')};$('#all-interests').onclick=()=>{journeyData.interests=[];saveJourney();go('home')}}
watch=function(){beforeWorldWatch();$('#main').insertAdjacentHTML('afterbegin',`<div class="watch-back"><button id="back-world">← Your world</button><span>/ Human, after all / Chapter 0${state.topic+1}</span></div>`);$('#back-world').onclick=()=>go('home');$('.controls').insertAdjacentHTML('afterend','<div class="session-chapters"><span id="chapter-one">01 / The proposition</span><span id="chapter-two">02 / The friction</span><span id="chapter-three">03 / A new perspective</span></div>');if(state.onStage&&state.avatar){$('.below-stage').insertAdjacentHTML('afterend',`<div class="backstage-bar"><div><strong>${esc(state.avatar.name)} is on stage. You’re backstage.</strong><p>Choose their next response or give them a line to say.</p></div><button id="send-direction">Direct my mind ↗</button></div>`);$('#send-direction').onclick=backstage}updateChapters();}
function updateChapters(){if(!$('#chapter-one'))return;const phase=state.turn<4?0:state.turn<9?1:2;['#chapter-one','#chapter-two','#chapter-three'].forEach((s,i)=>$(s).classList.toggle('active',i===phase))}
next=function(){beforeWorldNext();checkpoint();updateChapters()};
studio=function(){beforeWorldStudio();const a=state.avatar,done=journeyData.notes.some(n=>n.type==='appearance');$('#main').insertAdjacentHTML('afterbegin',`<div class="watch-back"><button id="studio-home">← Your world</button><span>/ Creator studio</span></div>`);$('#studio-home').onclick=()=>go('home');const panel=document.createElement('section');panel.className='world-section';panel.innerHTML=`<div class="world-section-head"><div><h2>A character is a work in progress.</h2><p>One clear next step. Your progress belongs to this device.</p></div></div><div class="studio-grid"><div class="panel"><span class="eyebrow">YOUR CREATOR JOURNEY</span><div class="journey">${[['Identity','A name, a point of view, and a boundary.',!!a],['Audition','Answer a difficult question in your own style.',journeyData.audition.length>0],['First appearance','Bring your character into the room.',done],['Find your voice','Direct a line from backstage.',journeyData.notes.some(n=>n.type==='direction')]].map(([title,desc,d],i)=>`<div class="journey-step ${d?'done':'active'}"><span class="step-orb">${d?'✓':'0'+(i+1)}</span><div><strong>${title}</strong><p>${desc}</p></div></div>`).join('')}</div><button class="primary" id="journey-next" style="margin-top:22px">${a?'Enter the audition room':'Create my mind'} ↗</button></div><div class="panel"><span class="eyebrow">CHARACTER NOTEBOOK</span><h3 style="margin-top:15px">A little history makes a mind.</h3>${journeyData.notes.length?journeyData.notes.slice(-4).reverse().map(n=>`<div class="your-signal"><strong>${esc(n.title)}</strong><p>${esc(n.text)}</p></div>`).join(''):'<p class="connection-line">Your first appearance, audition choices, and backstage directions will be collected here. This is your character’s authored history.</p>'}<p class="connection-line">No simulated followers or earnings are added to your character. This notebook records your actual prototype actions.</p></div></div>`;$('#main').append(panel);$('#journey-next').onclick=()=>a?audition():create();if($('#rehearse-studio'))$('#rehearse-studio').onclick=audition;}
function addNote(type,title,text){journeyData.notes.push({type,title,text,date:Date.now()});if(journeyData.notes.length>20)journeyData.notes.shift();saveJourney()}
const auditionQuestions=[{q:'The other speaker makes a good point against your position. What do you do?',options:[['Revise my claim','“That changes part of my view. Here is the narrower claim I can still defend.”'],['Ask for a concrete example','“Give me a real case. I want to understand where my position breaks down.”'],['Name the disagreement','“We may share the goal but disagree about the trade-off. Let’s name it.”']]},{q:'You are asked for a fact you cannot verify. How do you respond?',options:[['Admit uncertainty','“I cannot verify that. I would rather leave the question open than invent an answer.”'],['Separate belief from evidence','“That is my interpretation, not an established fact. Here is what would test it.”'],['Invite a source check','“Let’s send that to the evidence desk before we build an argument on it.”']]}];
function audition(round=0){if(!state.avatar){create();return}const a=state.avatar,q=auditionQuestions[round];modal(`<span class="eyebrow">THE AUDITION ROOM / ${round+1} OF 2</span><h2 id="modal-title">Let ${esc(a.name)} surprise us.</h2><div class="avatar-preview">${face(3)}</div><p style="color:var(--white)">${q.q}</p>${q.options.map(([title,line],i)=>`<button class="branch-card" data-audition="${i}"><strong>${title}</strong><span>${line}</span></button>`).join('')}<p style="font-size:10px;margin-top:15px">You are choosing authored sample responses. They will become part of your character notebook.</p>`);$$('[data-audition]').forEach(b=>b.onclick=()=>{const i=+b.dataset.audition;journeyData.audition[round]=i;addNote('audition',a.name+' · '+q.options[i][0],q.options[i][1]);if(round===0)audition(1);else auditionResult()})}
function auditionResult(){const a=state.avatar,line=auditionQuestions[0].options[journeyData.audition[0]??0][1];modal(`<span class="eyebrow">YOUR MIND HAS SOMETHING TO SAY</span><h2 id="modal-title">A first impression.<br>A real point of view.</h2><div class="backstage-preview">${esc(line)}</div><div class="profile-lore"><i>◎</i><p>${esc(a.name)} will enter the panel with the response you chose.</p></div><div class="note">The audition is a creative choice, not a hidden quality score. You can return and choose a different response.</div><div class="modal-actions"><button class="secondary" id="return-studio">My notebook</button><button class="primary" id="audition-stage">Take my seat ↗</button></div>`);$('#return-studio').onclick=()=>go('studio');$('#audition-stage').onclick=()=>{close();state.onStage=true;openEpisode(0);state.branch=[['ECHO',`A new perspective joins us. Welcome, ${a.name}. What do you do when someone challenges your position?`],[2,line.replace(/[“”]/g,'')],[1,'That gives us a useful starting point. Let’s test it against a concrete situation.'],['ECHO','Your creator is backstage. They can choose the next line while we continue.']];next();stageEvent(a.name.toUpperCase()+' TAKES THE STAGE')}}
function backstage(){if(!state.avatar)return;const a=state.avatar;modal(`<span class="eyebrow">BACKSTAGE / ONLY YOU AND YOUR MIND</span><h2 id="modal-title">Give ${esc(a.name)} a direction.</h2><p>Choose the next move, or write the exact line your character will say in this demo.</p><div class="choices"><button class="choice" data-cue="example">Ask for an example</button><button class="choice" data-cue="rethink">Change my position</button><button class="choice" data-cue="uncertain">Admit uncertainty</button></div><label for="director-line">Your authored line</label><textarea id="director-line" maxlength="260" placeholder="What should your character say next?"></textarea><div class="note">This prototype speaks your text as written. A future AI connection would interpret a direction instead.</div><div class="modal-actions"><button class="secondary" id="cancel-cue">Keep listening</button><button class="primary" id="send-cue">Send to the stage ↗</button></div>`);const lines={example:'Can we take one concrete example? I want to see how your idea works for an actual person.',rethink:'I have changed my mind on one part of this. The trade-off is more complicated than I first assumed.',uncertain:'I do not have enough evidence to be confident about that. Let’s be honest about what we still do not know.'};$$('[data-cue]').forEach(b=>b.onclick=()=>{$('#director-line').value=lines[b.dataset.cue];$$('[data-cue]').forEach(x=>x.classList.toggle('selected',x===b))});$('#cancel-cue').onclick=close;$('#send-cue').onclick=()=>{const line=$('#director-line').value.trim();if(!line){toast('Choose a direction or write a line first');return}addNote('direction','A line from backstage',line);close();state.branch=[[2,line],['ECHO',`${a.name} brings a new angle. Let’s give that question some room.`]];state.branchActive=null;state.playing=true;next();stageEvent('YOUR DIRECTION REACHED THE STAGE')}}
profile=function(i){const p=getPerson(i),isOwn=i===3;modal(`<span class="eyebrow">${isOwn?'YOUR ORIGINAL MIND':'ORIGINAL AI CHARACTER / '+p.creator}</span><h2 id="modal-title">${esc(p.name)} has a point.</h2><div class="avatar-preview">${face(i)}</div><p>${esc(p.bio||'A mind you are still getting to know.')}</p>${!isOwn?`<div class="backstage-preview">“${p.stance}”</div><div class="profile-lore"><i>◌</i><p>${i===0?'Wants possibility to reach the people who need it. Will change position when optimism needs a boundary.':i===1?'Asks who benefits, who decides, and what the evidence actually says. Skepticism is a method, not a personality flaw.':'Brings the conversation back to human experience. Listens for the person missing from the argument.'}</p></div>`:`<div class="your-signal"><strong>${esc(state.avatar.topic)}</strong><p>${esc(state.avatar.boundary)}</p></div>`}<div class="note">${isOwn?'Your identity and notebook are saved in this browser.':'Follow to keep this character in your home. The cast and stories are authored for this prototype.'}</div><div class="modal-actions"><button class="secondary" id="profile-follow">${isOwn?'Open my studio':state.following.includes(p.name)?'Following ✓':'Keep them in my orbit +'}</button><button class="primary" id="profile-hear">${isOwn?'Go backstage':'Hear their perspective'} ↗</button></div>`);$('#profile-follow').onclick=()=>{if(isOwn){go('studio');return}toggleFollow(i);$('#profile-follow').textContent=state.following.includes(p.name)?'Following ✓':'Keep them in my orbit +'};$('#profile-hear').onclick=()=>{if(isOwn){close();if(state.view!=='watch'){state.onStage=true;openEpisode(0)}backstage()}else{openEpisode(i===2?2:0);state.turn=i===1?2:1;updateTurn();stageEvent(p.name.toUpperCase()+' / A DIFFERENT PERSPECTIVE')}}}
results=function(){checkpoint();const finished=state.turn>=scripts[state.topic].length-1&&!state.branchActive;if(finished&&!journeyData.completed.includes(state.topic)){journeyData.completed.push(state.topic);saveJourney()}state.playing=false;const upcoming=[0,1,2].find(i=>!journeyData.completed.includes(i)&&i!==state.topic);modal(`<span class="eyebrow">${finished?'CHAPTER COMPLETE':'YOUR CONVERSATION SO FAR'}</span><h2 id="modal-title">${finished?'A different perspective.<br>Something to take with you.':'A good place to pause.'}</h2><p>${finished?'You have reached the end of this authored episode. Your progress is saved.':'Your place is saved. Come back when you want to hear the rest.'}</p><div class="stats"><div class="stat"><b>${journeyData.completed.length}/3</b><span>Season chapters finished</span></div><div class="stat"><b>${state.actions.challenges}</b><span>Your session challenges</span></div><div class="stat"><b>${state.following.length}</b><span>Minds in your orbit</span></div></div><div class="episode-end-card"><span class="eyebrow">${upcoming!==undefined?'WHEN YOU’RE CURIOUS AGAIN':'YOUR NEXT CHAPTER'}</span><h3>${upcoming!==undefined?worlds[upcoming].title:'Bring a mind of your own.'}</h3><p>${upcoming!==undefined?worlds[upcoming].desc:'You have explored this first season. Now imagine the perspective you would add.'}</p></div><div class="modal-actions"><button class="secondary" id="end-home">Back to my world</button><button class="primary" id="next-chapter">${!finished?'Keep watching':upcoming!==undefined?'Next chapter ↗':state.avatar?'My studio ↗':'Create a mind ↗'}</button></div><p style="font-size:10px;margin-top:18px">No countdown. No autoplay into the next episode. Your time is yours.</p>`);$('#end-home').onclick=()=>go('home');$('#next-chapter').onclick=()=>{if(!finished){close();state.playing=true;updateTurn()}else if(upcoming!==undefined)openEpisode(upcoming);else if(state.avatar)go('studio');else{close();create()}}}
function activity(){modal(`<span class="eyebrow">YOUR WORLD / ACTUAL LOCAL ACTIVITY</span><h2 id="modal-title">A thread to come back to.</h2>${state.avatar?`<div class="your-signal"><strong>${esc(state.avatar.name)} · Your mind</strong><p>${journeyData.audition.length?'An audition is saved. Your next appearance can start with that response.':'The audition room is ready whenever you are.'}</p></div>`:''}${state.following.length?`<div class="your-signal"><strong>${state.following.length} minds in your orbit</strong><p>${esc(state.following.join(', '))}</p></div>`:''}<div class="your-signal"><strong>${journeyData.completed.length} of 3 chapters complete</strong><p>${latestProgress()?'You have an unfinished episode waiting at your saved place.':'Explore the first season at your own pace.'}</p></div><div class="note">These are local reminders about your actions. No scheduled broadcast, push notification, or new episode is being claimed.</div><div class="modal-actions"><button class="secondary" id="activity-home">My world</button><button class="primary" id="activity-studio">${state.avatar?'My studio':'Create a mind'} ↗</button></div>`);$('#activity-home').onclick=()=>go('home');$('#activity-studio').onclick=()=>state.avatar?go('studio'):(close(),create())}
render=function(){document.body.classList.toggle('world-mode',state.view==='home');document.body.classList.toggle('creator-theme',state.view==='studio');if(state.view==='home'){close();document.body.classList.remove('theater');home();$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view==='home'));$('#balance').textContent=state.balance;initFaces()}else{beforeWorldRender();if(state.onStage&&state.avatar&&!journeyData.notes.some(n=>n.type==='appearance'&&n.text.includes(state.avatar.name))){addNote('appearance','A first appearance',state.avatar.name+' entered the demo panel.')}}};
$('nav').innerHTML='<button class="nav" data-view="home"><span class="nav-symbol">◌</span>Your world</button><button class="nav" data-view="watch"><span class="nav-symbol">◉</span>On stage</button><button class="nav" data-view="discover"><span class="nav-symbol">⌘</span>Discover</button><button class="nav" data-view="studio"><span class="nav-symbol">✳</span>My studio</button>';
$$('.nav').forEach(b=>b.onclick=()=>{if(b.dataset.view==='watch'){openEpisode(state.topic,true)}else go(b.dataset.view)});$('.brand').onclick=e=>{e.preventDefault();go('home')};$('.account').insertAdjacentHTML('afterbegin','<button class="notification-button" id="activity" aria-label="Your activity">◌</button>');$('#activity').onclick=activity;$('.user').onclick=()=>go('studio');$('.user').setAttribute('role','button');$('.user').setAttribute('tabindex','0');$('.user').setAttribute('aria-label','Open my studio');$('.user').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go('studio')}};
setInterval(()=>{if(state.view==='watch'&&state.playing){checkpoint();updateChapters()}},5000);
window.addEventListener('pagehide',checkpoint);
state.view=location.hash.match(/episode-\d/)?'watch':'home';render();
